            env::set_var("APPDATA", temp_dir.path().join("AppData/Roaming"));
            env::set_var("LOCALAPPDATA", temp_dir.path().join("AppData/Local"));
        }

        Self { _temp_dir: temp_dir }
    }
}

impl Drop for TestEnv {
    fn drop(&mut self) {
        unsafe {
            env::remove_var("HOME");
            env::remove_var("XDG_CONFIG_HOME");
            // ... 其他
        }
    }
}
```

