```rust
// tests/common/mod.rs
use std::env;
use std::net::SocketAddr;
use tempfile::TempDir;
use tokio::net::TcpListener;

pub struct TestEnv {
    _dir: TempDir,
}

impl TestEnv {
    pub fn new() -> Self {
        let dir = tempfile::tempdir().expect("failed to create temp dir");
        let home = dir.path();

        let vars = [
            ("HOME", home.to_path_buf()),
            ("USERPROFILE", home.to_path_buf()),
            ("XDG_CONFIG_HOME", home.join(".config")),
            ("XDG_DATA_HOME", home.join(".local/share")),
            ("XDG_CACHE_HOME", home.join(".cache")),
            ("APPDATA", home.join("AppData/Roaming")),
            ("LOCALAPPDATA", home.join("AppData/Local")),
        ];

        for (k, v) in vars {
            unsafe { env::set_var(k, v) };
        }

        Self { _dir: dir }
    }
}

impl Drop for TestEnv {
    fn drop(&mut self) {
        let keys = [
            "HOME", "USERPROFILE", "XDG_CONFIG_HOME", "XDG_DATA_HOME",
            "XDG_CACHE_HOME", "APPDATA", "LOCALAPPDATA",
        ];
        for k in keys {
            unsafe { env::remove_var(k) };
        }
    }
}

pub async fn random_port() -> u16 {
    let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
    listener.local_addr().unwrap().port()
    // listener drop 后端口释放，有极小概率被占用，但通常足够。
    // 更安全的方式是保留 listener 直到 server 启动，或使用 portpicker。
}
```

等等，`random_port` 函数中 listener drop 后端口释放，有竞态条件。更好的做法是返回 `(TcpListener, u16)` 或者使用 `portpicker`。或者如果测试服务器需要绑定，应该直接传递 `TcpListener` 给服务器。

更健壮的端口夹具：

```rust
pub struct TestPort {
    pub port: u16,
    _listener: TcpListener, // 保持存活直到服务器真正绑定
}

pub async fn reserve_port() -> TestPort {
    let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
    let port = listener.local_addr().unwrap().port();
    TestPort { port, _listener: listener }
}
```

但这也有问题，如果服务器要绑定同一个端口，需要 reuse addr 或者关闭 listener。实际上对于测试，通常：
1. 绑定端口 0 得到端口号，关闭 listener，立即用该端口启动服务器（竞态极小）。
2. 或者使用 `portpicker::pick_unused_port()`。
3. 或者如果服务器代码支持传入 `TcpListener`，直接传进去。

我推荐使用 `portpicker` crate，简单且跨平台。

```rust
let port = portpicker::pick_unused_port().expect("no ports free");
```

对于环境变量，如果项目使用 Rust 2024，`set_var` 是 unsafe。我应该提到这一点。

另外，可以建议使用 `#[serial]` 属性，并且如果测试很多，考虑用 `serial_test::file_serial` 或 `#[serial(config)]` 分组。

还有一个高级技巧：使用 `temp-env` crate 的 `with_vars` 闭包方式，它内部处理了恢复，但仍然是全局的，所以仍需 `serial`。

```rust
temp_env::with_vars(
    [("HOME", Some(temp_dir.path())), ("XDG_CONFIG_HOME", Some(...))],
    || {
        // test code
    },
);
```

但 `with_vars` 是同步闭包，异步测试需要 `futures::executor::block_on` 或者使用 `tokio::task::block_in_place`。所以可能不如自定义 `TestEnv` 结构体方便。

